#include <utility>

class FieldKit
{
public:
    explicit FieldKit(int packages)
        : load_(packages)
    {
    }

    FieldKit(const FieldKit&) = delete;
    FieldKit& operator=(const FieldKit&) = delete;

    FieldKit(FieldKit&& other)
        : load_(std::move(other.load_))
    {
    }

    ~FieldKit() = default;

    bool empty() const
    {
        return load_.packages() == 0;
    }

    int packages() const
    {
        return load_.packages();
    }

private:
    SupplyLoad load_;
};
